effect.shader:
// `sat_scale` do Sapphire (legacy luma, 0.3/0.59/0.11 — Rec.601 arredondado). O alfa não é tocado.
vec4 satScale(vec4 c, float s) {
    float y = 0.3 * c.r + 0.59 * c.g + 0.11 * c.b;
    return vec4(y + (c.rgb - y) * s, c.a);
}

// bounce(x, b) = b − |mod(x, 2b) − b|. Com b = 0 o resultado é 0 (o plugin trata o degenerado
// quieto; se alguém colocar Round com Dest B = 0, cai aqui também).
vec4 bounce4(vec4 x, vec4 b) {
    vec4 twoB = 2.0 * b;
    vec4 m = mod(x, max(twoB, vec4(1e-30)));
    vec4 r = b - abs(m - b);
    return mix(r, vec4(0.0), vec4(lessThanEqual(abs(b), vec4(1e-30))));
}

// Bitwise em 8 bits, canal a canal. O plugin converte para inteiro antes da operação.
vec4 andBits(vec4 a, vec4 b) {
    ivec4 ia = ivec4(clamp(a, 0.0, 1.0) * 255.0 + 0.5);
    ivec4 ib = ivec4(clamp(b, 0.0, 1.0) * 255.0 + 0.5);
    return vec4(ia & ib) / 255.0;
}
vec4 orBits(vec4 a, vec4 b) {
    ivec4 ia = ivec4(clamp(a, 0.0, 1.0) * 255.0 + 0.5);
    ivec4 ib = ivec4(clamp(b, 0.0, 1.0) * 255.0 + 0.5);
    return vec4(ia | ib) / 255.0;
}
vec4 xorBits(vec4 a, vec4 b) {
    ivec4 ia = ivec4(clamp(a, 0.0, 1.0) * 255.0 + 0.5);
    ivec4 ib = ivec4(clamp(b, 0.0, 1.0) * 255.0 + 0.5);
    return vec4(ia ^ ib) / 255.0;
}

// Round do Sapphire: snap(i1 / i2) · i2. Com i2 = 0 o quociente estoura; o plugin pisa igual
// (resultado NaN/∞). Devolver 0 ali evita a propagação de NaN sem reaproximar a conta.
vec4 roundOp(vec4 a, vec4 b) {
    vec4 safeB = mix(b, vec4(1e-30), vec4(equal(b, vec4(0.0))));
    vec4 q = floor(a / safeB + 0.5);
    return mix(q * b, vec4(0.0), vec4(equal(b, vec4(0.0))));
}

vec4 aplicarGrading(vec4 c, float lights, float darks, float sat) {
    vec4 g = satScale(c, sat);
    return (lights - darks) * g + darks;
}

void main() {
    vec4 srcA = texture(inputImg, acScreenNorm);
    // SourceB em "None" (textura 1×1 transparente, como o `empty="transparent"` entrega) =
    // vec4(0,0,0,0), como o AE trata.
    vec4 srcB = textureSize(sourceB, 0).x <= 1 ? vec4(0.0) : texture(sourceB, acScreenNorm);

    vec4 a = swapInputs ? srcB : srcA;
    vec4 b = swapInputs ? srcA : srcB;

    vec4 i1 = aplicarGrading(a, aLights, aDarks, aSaturation);
    vec4 i2 = aplicarGrading(b, bLights, bDarks, bSaturation);

    vec4 d;
    if (operation == 0) {           // Add
        d = i1 + i2;
    } else if (operation == 1) {    // Subtract
        d = i1 - i2;
    } else if (operation == 2) {    // Multiply
        d = i1 * i2;
    } else if (operation == 3) {    // Divide
        d = i1 / i2;
    } else if (operation == 4) {    // Screen
        d = i1 + i2 - i1 * i2;
    } else if (operation == 5) {    // Average
        d = 0.5 * (i1 + i2);
    } else if (operation == 6) {    // Overlay
        vec4 screenV = i1 + i2 - i1 * i2;
        vec4 multiV = i1 * i2;
        d = mix(2.0 * multiV, 2.0 * screenV - 1.0, vec4(greaterThan(i2, vec4(0.5))));
    } else if (operation == 7) {    // Minimum
        d = min(i1, i2);
    } else if (operation == 8) {    // Maximum
        d = max(i1, i2);
    } else if (operation == 9) {    // Difference
        d = abs(i1 - i2);
    } else if (operation == 10) {   // Xor (triangular)
        d = bounce4(clamp(i1, 0.0, 1.0) + clamp(i2, 0.0, 1.0), vec4(1.0));
    } else if (operation == 11) {   // Xor Bits
        d = xorBits(i1, i2);
    } else if (operation == 12) {   // And Bits
        d = andBits(i1, i2);
    } else if (operation == 13) {   // Or Bits
        d = orBits(i1, i2);
    } else if (operation == 14) {   // Mod
        vec4 safe = mix(i2, vec4(1e-30), vec4(equal(i2, vec4(0.0))));
        d = i1 - i2 * floor(i1 / safe);
    } else if (operation == 15) {   // Bounce
        d = bounce4(i1, i2);
    } else {                        // Round
        d = roundOp(i1, i2);
    }

    fragColor = aplicarGrading(d, destLights, destDarks, destSaturation);
}
